mapper.sql:
SELECT DISTINCT deviceId AS deviceId, LOWER(deviceNumber) AS deviceNumber, searchPriority, sortingValue
FROM
(
SELECT
       devices.id AS deviceId,
       devices.number AS deviceNumber,

(
    COALESCE(CASE WHEN devices.number LIKE #{value} THEN 16 END, 0) +
    COALESCE(CASE WHEN devices.imei LIKE #{value} THEN 8 END, 0) +
    COALESCE(CASE WHEN devices.phone LIKE #{value} THEN 4 END, 0) +
    COALESCE(CASE WHEN devices.description LIKE #{value} THEN 2 END, 0)
    )

0
AS searchPriority,
(
    CASE
        WHEN 'STATUS' = #{sortBy} THEN
            CAST(
                (CASE
                    WHEN (UNIX_TIMESTAMP(NOW()) * 1000 - devices.lastupdate) < (2 * 3600 * 1000) THEN '1_green'
                    WHEN (UNIX_TIMESTAMP(NOW()) * 1000 - devices.lastupdate) < (4 * 3600 * 1000) THEN '2_yellow'
                    ELSE '3_red'
                END) AS CHAR(100)
            )
        WHEN 'LAST_UPDATE' = #{sortBy} THEN CAST(devices.lastUpdate AS CHAR(100))
        WHEN 'NUMBER' = #{sortBy} THEN CAST(LOWER(devices.number) AS CHAR(100))
        WHEN 'IMEI' = #{sortBy} THEN CAST(mdm_resolve_device_property(devices.imei, JSON_UNQUOTE(JSON_EXTRACT(devices.infojson, '$.imei'))) AS CHAR(100))
        WHEN 'PHONE' = #{sortBy} THEN CAST(mdm_resolve_device_property(devices.phone, JSON_UNQUOTE(JSON_EXTRACT(devices.infojson, '$.phone'))) AS CHAR(100))
        WHEN 'MODEL' = #{sortBy} THEN CAST(LOWER(JSON_UNQUOTE(JSON_EXTRACT(devices.infojson, '$.model'))) AS CHAR(100))
        WHEN 'PERMISSIONS' = #{sortBy} THEN CAST(mdm_device_permissions_index(devices.info) AS CHAR(100))
        WHEN 'INSTALLATIONS' = #{sortBy} THEN CAST(COALESCE(devicestatuses.applicationsStatus, 'FAILURE') AS CHAR(100))
        WHEN 'FILES' = #{sortBy} THEN CAST(COALESCE(devicestatuses.configFilesStatus, 'OTHER') AS CHAR(100))
        WHEN 'CONFIGURATION' = #{sortBy} THEN CAST(LOWER(configurations.name) AS CHAR(100))
        WHEN 'DESCRIPTION' = #{sortBy} THEN CAST(LOWER(COALESCE(devices.description, '')) AS CHAR(100))
        WHEN 'GROUP' = #{sortBy} THEN CAST(COALESCE(LOWER(groups.name), '') AS CHAR(100))
        WHEN 'LAUNCHER_VERSION' = #{sortBy} THEN CAST(mdm_device_launcher_version(applications.pkg, devices.info) AS CHAR(100))
        WHEN 'BATTERY_LEVEL' = #{sortBy} THEN CAST(LPAD(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(devices.infojson, '$.batteryLevel')), '0'), 3, '0') AS CHAR(100))
        WHEN 'DEFAULT_LAUNCHER' = #{sortBy} THEN CAST(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(devices.infojson, '$.defaultLauncher')), 'unknown') AS CHAR(100))
        WHEN 'MDM_MODE' = #{sortBy} THEN CAST(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(devices.infojson, '$.mdmMode')), '') AS CHAR(100))
        WHEN 'KIOSK_MODE' = #{sortBy} THEN CAST(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(devices.infojson, '$.kioskMode')), '') AS CHAR(100))
        WHEN 'ANDROID_VERSION' = #{sortBy} THEN CAST(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(devices.infojson, '$.androidVersion')), '') AS CHAR(100))
        WHEN 'ENROLLMENT_DATE' = #{sortBy} THEN CAST(devices.enrollTime AS CHAR(100))
        WHEN 'SERIAL' = #{sortBy} THEN CAST(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(devices.infojson, '$.serial')), '') AS CHAR(100))
        WHEN 'PUBLICIP' = #{sortBy} THEN CAST(COALESCE(devices.publicIp, '') AS CHAR(100))
        WHEN 'CUSTOM1' = #{sortBy} THEN CAST(LOWER(devices.custom1) AS CHAR(100))
        WHEN 'CUSTOM2' = #{sortBy} THEN CAST(LOWER(devices.custom2) AS CHAR(100))
        WHEN 'CUSTOM3' = #{sortBy} THEN CAST(LOWER(devices.custom3) AS CHAR(100))
        ELSE ''
    END
) AS sortingValue
FROM devices
INNER JOIN users ON users.id = #{userId}
LEFT JOIN devicestatuses ON devices.id = devicestatuses.deviceId
LEFT JOIN configurations ON devices.configurationId = configurations.id
LEFT JOIN applicationversions ON configurations.mainAppId = applicationversions.id
LEFT JOIN applications ON applications.id = applicationversions.applicationid
LEFT JOIN devicegroups ON devices.id = devicegroups.deviceId
LEFT JOIN groups ON devicegroups.groupId = groups.id
LEFT JOIN userdevicegroupsaccess access ON groups.id = access.groupId AND access.userId = users.id
WHERE devices.customerId = #{customerId}
AND (users.allDevicesAvailable = TRUE OR NOT access.id IS NULL)

    AND (
    devices.number LIKE #{value}
    OR devices.description LIKE #{value}
    OR devices.imei LIKE #{value}
    OR devices.phone LIKE #{value}
    OR devices.publicIp LIKE #{value}
    OR JSON_UNQUOTE(JSON_EXTRACT(devices.infojson, '$.imei')) LIKE #{value}
    OR JSON_UNQUOTE(JSON_EXTRACT(devices.infojson, '$.phone')) LIKE #{value}
    OR JSON_UNQUOTE(JSON_EXTRACT(devices.infojson, '$.model')) LIKE #{value}
    OR JSON_UNQUOTE(JSON_EXTRACT(devices.infojson, '$.serial')) LIKE #{value}
    OR devices.custom1 LIKE #{value}
    OR devices.custom2 LIKE #{value}
    OR devices.custom3 LIKE #{value}
    OR devices.oldNumber LIKE #{value}
    OR configurations.name LIKE #{value}
    OR groups.name LIKE #{value}
    )


    AND (
    devices.number = #{value}
    OR devices.fastSearch = #{value}
    )


    and devices.imeiUpdateTs / 1000 > unix_timestamp(now() - interval 1 hour)


    AND (
    groups.id = #{groupId}
    )


    AND (
    configurations.id = #{configurationId}
    )


    AND (
    devices.lastUpdate >= #{dateFromMillis}
    )


    AND (
    devices.lastUpdate <= #{dateToMillis}
    )


    AND (
    devices.lastUpdate <= unix_timestamp(now()) * 1000 - #{onlineEarlierMillis}
    )


    AND (
    devices.lastUpdate >= unix_timestamp(now()) * 1000 - #{onlineLaterMillis}
    )


    AND (
    devices.enrollTime >= #{enrollmentDateFromMillis}
    )


    AND (
    devices.enrollTime <= #{enrollmentDateToMillis}
    )


    AND (
    (JSON_UNQUOTE(JSON_EXTRACT(devices.infojson, '$.mdmMode')) = #{mdmMode})
    )


    AND (
    (JSON_UNQUOTE(JSON_EXTRACT(devices.infojson, '$.kioskMode')) = #{kioskMode})
    )


    AND (
    JSON_UNQUOTE(JSON_EXTRACT(devices.infojson, '$.androidVersion')) = #{androidVersion}
    )


    AND (
    mdm_device_launcher_version(applications.pkg, devices.info) = #{launcherVersion}
    )


    AND (
    devicestatuses.applicationsStatus = #{installationStatus}
    )

) allowedDevicesInner
ORDER BY sortingValue DESC,
        searchPriority, LOWER(deviceNumber)

LIMIT #{offset}, #{pageSize}

